import React from "react";
import "./Home.css"; // styles defined later

export default function HomePage() {
  return (
    <div>

      {/* ABOUT SECTION / HERO SECTION */}
      <section id="about-section" className="about-hero">
        <div className="overlay">
          <h1>About Our NGO</h1>
          <p>
            We are committed to creating a better future through education,
            empowerment, and sustainable community development.
          </p>
        </div>
      </section>

      {/* HOME CONTENT BELOW ABOUT */}
      <section id="home-section" className="home-body">
        <h2>Welcome to Our NGO Portal</h2>
        <p>
          Explore volunteering opportunities, events, and community programs.
        </p>
      </section>

      {/* EVENTS SECTION */}
      <section id="events-section" className="events-area">
        <h2>Upcoming Events</h2>
        <p>Stay updated with our latest programs and initiatives.</p>
      </section>

    </div>
  );
}
